+    fn start_visual_selection(
+        &mut self,
+        kind: VisualSelectionKind,
+        right_content: &str,
+    ) -> Vec<UiAction> {
+        let lines = self.text_lines_for_pane(self.focus, right_content);
+        let position = self.current_text_position(self.focus, kind, &lines);
+        self.visual_selection = Some(VisualSelection {
+            pane: self.focus,
+            kind,
+            anchor: position,
+            cursor: position,
+        });
+        self.mode = kind.ui_mode();
+        Vec::new()
+    }
+
+    fn change_visual_selection_kind(
+        &mut self,
+        kind: VisualSelectionKind,
+        right_content: &str,
+    ) {
+        let Some(selection) = self.visual_selection else {
+            let _ = self.start_visual_selection(kind, right_content);
+            return;
+        };
+        let lines = self.text_lines_for_pane(selection.pane, right_content);
+        self.visual_selection = Some(VisualSelection {
+            pane: selection.pane,
+            kind,
+            anchor: clamp_text_position(kind, selection.anchor, &lines),
+            cursor: clamp_text_position(kind, selection.cursor, &lines),
+        });
+        self.mode = kind.ui_mode();
+    }
+
+    fn move_visual_selection(
+        &mut self,
+        row_delta: isize,
+        column_delta: isize,
+        right_content: &str,
+    ) {
+        let Some(selection) = self.visual_selection else {
+            return;
+        };
+        let lines = self.text_lines_for_pane(selection.pane, right_content);
+        let next = TextPosition {
+            row: add_signed(selection.cursor.row, row_delta),
+            column: add_signed(selection.cursor.column, column_delta),
+        };
+        if let Some(active) = self.visual_selection.as_mut() {
+            active.cursor = clamp_text_position(active.kind, next, &lines);
+        }
+    }
+
+    fn copy_visual_selection(&mut self, right_content: &str) -> Vec<UiAction> {
+        let Some(selection) = self.visual_selection else {
+            return Vec::new();
+        };
+        let lines = self.text_lines_for_pane(selection.pane, right_content);
+        let text = selected_text(selection, &lines);
+        self.clear_visual_selection();
+        self.mode = UiMode::Command;
+        self.show_copy_notice(&text);
+        vec![UiAction::CopySelection(text)]
+    }
+
+    fn copy_current_line(&mut self, right_content: &str) -> Vec<UiAction> {
+        let lines = self.text_lines_for_pane(self.focus, right_content);
+        let position = self.current_text_position(self.focus, VisualSelectionKind::Line, &lines);
+        let text = lines.get(position.row).cloned().unwrap_or_default();
+        self.show_copy_notice(&text);
+        vec![UiAction::CopySelection(text)]
+    }
+
+    fn show_copy_notice(&mut self, text: &str) {
+        self.show_status_notice(
+            format!("copied {} chars", text.chars().count()),
+            Duration::from_secs(STATUS_NOTICE_SECONDS),
+        );
+    }
+
+    fn clear_visual_selection(&mut self) {
+        self.visual_selection = None;
+    }
+
+    fn text_lines_for_pane(&self, pane: PaneFocus, right_content: &str) -> Vec<String> {
+        match pane {
+            PaneFocus::Left => self.left_text_lines(),
+            PaneFocus::Right => self.right_visible_text_lines(right_content),
+        }
+    }
+
+    fn right_visible_text_lines(&self, right_content: &str) -> Vec<String> {
+        text_lines(&self.visible_right_content(right_content))
+    }
+
+    fn left_text_lines(&self) -> Vec<String> {
+        let inner_width = usize::from(self.layout().left_width.saturating_sub(2).max(1));
+        let mut lines = vec![truncate_to_width(
+            if self.control_selected == 0 {
+                "> work-leaf  command"
+            } else {
+                "  work-leaf  command"
+            },
+            inner_width,
+        )];
+        for (visible_position, agent_index) in self.visible_agent_indices().iter().enumerate() {
+            let agent = &self.agents[*agent_index];
+            lines.push(compact_agent_row(
+                agent,
+                self.control_selected == visible_position + 1,
+                inner_width,
+            ));
+            if !agent.modified_files.is_empty() {
+                lines.push(truncate_to_width(
+                    &format!(
+                        "    files: {}",
+                        agent
+                            .modified_files
+                            .iter()
+                            .map(|path| path.display().to_string())
+                            .collect::<Vec<_>>()
+                            .join(", ")
+                    ),
+                    inner_width,
+                ));
+            }
+            for (label, agents) in [
+                ("conflicts", &agent.conflicting_agents),
+                ("depends-on", &agent.depends_on),
+                ("depended-on-by", &agent.depended_on_by),
+            ] {
+                if !agents.is_empty() {
+                    lines.push(truncate_to_width(
+                        &format!(
+                            "    {label}: {}",
+                            agents
+                                .iter()
+                                .map(AgentId::as_str)
+                                .collect::<Vec<_>>()
+                                .join(", ")
+                        ),
+                        inner_width,
+                    ));
+                }
+            }
+        }
+        lines
+    }
+
+    fn current_text_position(
+        &self,
+        pane: PaneFocus,
+        kind: VisualSelectionKind,
+        lines: &[String],
+    ) -> TextPosition {
+        let row = match pane {
+            PaneFocus::Left => self.left_control_text_row(),
+            PaneFocus::Right => lines.len().saturating_sub(1),
+        };
+        let row = row.min(lines.len().saturating_sub(1));
+        let column = match (pane, kind) {
+            (_, VisualSelectionKind::Line) | (PaneFocus::Left, _) => 0,
+            (PaneFocus::Right, _) => last_char_column(lines.get(row).map_or("", String::as_str)),
+        };
+        clamp_text_position(kind, TextPosition { row, column }, lines)
+    }
+
+    fn left_control_text_row(&self) -> usize {
+        if self.control_selected == 0 {
+            return 0;
+        }
+        let mut current_row = 1;
+        for (visible_position, agent_index) in self.visible_agent_indices().iter().enumerate() {
+            if self.control_selected == visible_position + 1 {
+                return current_row;
+            }
+            current_row += 1;
+            let agent = &self.agents[*agent_index];
+            if !agent.modified_files.is_empty() {
+                current_row += 1;
+            }
+            for linked_agents in [
+                &agent.conflicting_agents,
+                &agent.depends_on,
+                &agent.depended_on_by,
+            ] {
+                if !linked_agents.is_empty() {
+                    current_row += 1;
+                }
+            }
+        }
+        0
+    }
+
+    fn apply_visual_selection(&self, buffer: &mut Buffer, visible_right_content: &str) {
+        let Some(selection) = self.visual_selection else {
+            return;
+        };
+        if !self.mode.is_visual() {
+            return;
+        }
+        match selection.pane {
+            PaneFocus::Left => {
+                let lines = self.left_text_lines();
+                self.apply_left_visual_selection(buffer, selection, &lines);
+            }
+            PaneFocus::Right => {
+                let lines = text_lines(visible_right_content);
+                self.apply_right_visual_selection(buffer, selection, &lines);
+            }
+        }
+    }
+
+    fn apply_left_visual_selection(
+        &self,
+        buffer: &mut Buffer,
+        selection: VisualSelection,
+        lines: &[String],
+    ) {
+        let Some((x, y, width, height)) = self.pane_inner_area(PaneFocus::Left) else {
+            return;
+        };
+        let width = usize::from(width);
+        let height = usize::from(height);
+        for (row, start, end) in selected_ranges(selection, lines) {
+            if row >= height {
+                continue;
+            }
+            for column in start..end.min(width) {
+                set_reversed(buffer, x.saturating_add(column as u16), y.saturating_add(row as u16));
+            }
+        }
+    }
+
+    fn apply_right_visual_selection(
+        &self,
+        buffer: &mut Buffer,
+        selection: VisualSelection,
+        lines: &[String],
+    ) {
+        let Some((x, y, width, height)) = self.pane_inner_area(PaneFocus::Right) else {
+            return;
+        };
+        let width = usize::from(width.max(1));
+        let height = usize::from(height);
+        let row_offsets = visual_row_offsets(lines, width);
+        for (row, start, end) in selected_ranges(selection, lines) {
+            let Some(row_offset) = row_offsets.get(row).copied() else {
+                continue;
+            };
+            for column in start..end {
+                let visual_row = row_offset.saturating_add(column / width);
+                if visual_row >= height {
+                    continue;
+                }
+                let visual_column = column % width;
+                set_reversed(
+                    buffer,
+                    x.saturating_add(visual_column as u16),
+                    y.saturating_add(visual_row as u16),
+                );
+            }
+        }
+    }
+
+    fn visual_cursor_position(&self, visible_right_content: &str) -> Option<(u16, u16)> {
+        let selection = self.visual_selection?;
+        let lines = match selection.pane {
+            PaneFocus::Left => self.left_text_lines(),
+            PaneFocus::Right => text_lines(visible_right_content),
+        };
+        let cursor = clamp_text_position(selection.kind, selection.cursor, &lines);
+        self.text_position_to_terminal_position(selection.pane, cursor, &lines)
+    }
+
+    fn text_position_to_terminal_position(
+        &self,
+        pane: PaneFocus,
+        position: TextPosition,
+        lines: &[String],
+    ) -> Option<(u16, u16)> {
+        let (x, y, width, height) = self.pane_inner_area(pane)?;
+        let width = usize::from(width.max(1));
+        let height = usize::from(height.max(1));
+        match pane {
+            PaneFocus::Left => Some((
+                y.saturating_add(position.row.min(height - 1) as u16),
+                x.saturating_add(position.column.min(width - 1) as u16),
+            )),
+            PaneFocus::Right => {
+                let offsets = visual_row_offsets(lines, width);
+                let row_offset = offsets.get(position.row).copied().unwrap_or_default();
+                let visual_row = row_offset.saturating_add(position.column / width);
+                Some((
+                    y.saturating_add(visual_row.min(height - 1) as u16),
+                    x.saturating_add((position.column % width) as u16),
+                ))
+            }
+        }
+    }
+
+    fn pane_inner_area(&self, pane: PaneFocus) -> Option<(u16, u16, u16, u16)> {
+        let layout = self.layout();
+        let body_height = self.height.saturating_sub(1);
+        let inner_height = body_height.saturating_sub(2);
+        match pane {
+            PaneFocus::Left if self.left_visible && layout.left_width > 0 => Some((
+                1,
+                1,
+                layout.left_width.saturating_sub(2),
+                inner_height,
+            )),
+            PaneFocus::Left => None,
+            PaneFocus::Right => Some((
+                layout.left_width.saturating_add(1),
+                1,
+                layout.right_width.saturating_sub(2),
+                inner_height,
+            )),
+        }
+    }
+
