+    }
+
     fn as_str(&self) -> &'static str {
         match self {
             Self::Command => "command",
             Self::Insert => "insert",
             Self::Prompt => "prompt",
+            Self::Visual => "visual",
+            Self::VisualLine => "visual-line",
