+
+impl VisualSelectionKind {
+    fn ui_mode(&self) -> UiMode {
+        match self {
+            Self::Character => UiMode::Visual,
+            Self::Line => UiMode::VisualLine,
+            Self::Block => UiMode::VisualBlock,
